/**
 * @module src/commands/global/get.js
 *
 * TSDoc autogenerated for get.js
 */

const fuzzysort = require('fuzzysort');

const { redBold } = require('../../utils/formatting');
const { send } = require('../../functions/player');
const { PLAYER } = require('../../events/event-types');

/**
 *
 * @param {import('../../models/player').Player} player
 * @param {string[]} args
 * @returns
 */
module.exports = (player, args) => {
  const { eventBus } = require('../../events/event-bus').get();

  const query = args.join(' ');
  const matches = fuzzysort.go(query, player.inventory, {
    key: 'name',
    threshold: -1000, // optional: filter bad matches
  });

  if (matches.length === 0) {
    send(player, redBold("You don't see that here!!"));
    return;
  }

  if (matches.length > 1) {
    const options = matches.map((m, i) => `${i + 1}. ${m.obj.name}`).join('\n');
    send(player, redBold('Multiple matches found:\n') + options + '\nPlease be more specific.');
    return;
  }

  const item = matches[0].obj;
  eventBus.emit(PLAYER.ITEM_USED, { player, item });
};
